const entrada = $input.all().map(i => i.json);
const falhou = entrada.find(l => l.error);

// a tabela vem da mais nova pra mais velha; o gráfico lê da esquerda pra direita
const linhas = entrada.filter(l => l.coletado_em).reverse();

const hora = valor => new Date(valor).toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit',
  month: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
});

const gráficos = [
  ['Membros e pessoas online', [['membros', 'Membros'], ['online', 'Online']]],
  ['Música', [['players', 'Players'], ['tocando', 'Tocando'], ['na_fila', 'Na fila']]],
  ['Memória (MB)', [['memoria_mb', 'Processo'], ['heap_mb', 'Heap do .NET']]],
  ['Servidores', [['servidores', 'Servidores']]],
].map(([título, séries]) => ({
  título,
  séries: séries.map(([campo, nome]) => ({
    label: nome,
    data: linhas.map(l => l[campo]),
    pointRadius: 0,
    tension: 0.2,
  })),
}));

// o JSON vai dentro de um <script>: sem "<" cru, nada dele fecha a tag antes da hora
const dados = JSON.stringify({ rótulos: linhas.map(l => hora(l.coletado_em)), gráficos })
  .replace(/</g, '\\u003c');

const última = linhas.at(-1);

const topo = falhou
  ? 'A tabela <code>aleph_stats</code> ainda não existe: ela nasce na primeira rodada do fluxo "AlephBot · Histórico de stats".'
  : última
    ? `Última coleta: ${hora(última.coletado_em)} · ${última.servidores} servidores · ${última.membros} membros · ${última.online} online`
    : 'Ainda não tem histórico: o fluxo "AlephBot · Histórico de stats" grava uma linha a cada 15 minutos.';

const html = `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>AlephBot · Painel</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 24px; }
  main { max-width: 1100px; margin: 0 auto; }
  #graficos { display: grid; grid-template-columns: repeat(auto-fit, minmax(420px, 1fr)); gap: 24px; }
  h2 { font-size: 1rem; }
</style>
</head>
<body>
<main>
  <h1>AlephBot · Painel</h1>
  <p>${topo}</p>
  <div id="graficos"></div>
</main>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4"></script>
<script>
  const { rótulos, gráficos } = ${dados};
  const lugar = document.getElementById('graficos');

  for (const g of gráficos) {
    const bloco = document.createElement('section');
    bloco.innerHTML = '<h2></h2><canvas></canvas>';
    bloco.querySelector('h2').textContent = g.título;
    lugar.appendChild(bloco);

    new Chart(bloco.querySelector('canvas'), {
      type: 'line',
      data: { labels: rótulos, datasets: g.séries },
      options: { interaction: { mode: 'index', intersect: false }, scales: { x: { ticks: { maxTicksLimit: 8 } } } },
    });
  }
</script>
</body>
</html>`;

return [{ json: { html } }];
